INSERT INTO `spouses` (`Id`, `TraitorId`, `Name`, `Remark`) VALUES ('441c37325626401a8df190a2a050789c','2cd03042493c7836d6e0870f1f49662b','王守泰','（1908—1991），吴县（今江苏苏州）人，王季烈四子、三叔王季点嗣子。1930年毕业于北平大学工学院电机系，历经英德实习、国民政府及抗战时期工作，主持多款水轮机、汽轮发电机设计制造，战后任教北洋大学。新中国成立后，历任多校教授，在汽轮机理论、能源研究有造诣，编著、译有多部相关著作。自幼嗜昆曲，师从名家，参与曲社、参演剧目，任昆曲研究会副会长，深研曲学，整理编著多部曲学著作，1991年10月23日逝世');
